-- =====================================================================
-- STAMP SAFAR — SEED DATA FOR SUPABASE
-- Stamps, Handicrafts, and Sample Listings
-- =====================================================================

-- 1. SEED HANDICRAFT PRODUCTS
ON CONFLICT (id) DO UPDATE SET
  price = EXCLUDED.price,
  name = EXCLUDED.name,
  stock = EXCLUDED.stock;

-- 2. SEED CORE STAMPS
ON CONFLICT (id) DO UPDATE SET
  price = EXCLUDED.price,
  stock = EXCLUDED.stock;
