INSERT INTO public.handicraft_products (id, name, artisan_name, state, district, category, price, stock, image, description, is_active)
VALUES
('wb-terracotta-bishnupur', 'Terracotta Temple Panel (Bishnupur)', 'Ramkrishna Pal (Demo)', 'West Bengal', 'Bankura', 'Terracotta', 2500, 10, 'https://images.unsplash.com/photo-1545601450-dae9fa90ec17?w=400&q=80', 'Hand-crafted terracotta panel depicting scenes from the Mahabharata, made using traditional techniques of Bishnupur.', true),
('wb-baluchari-saree', 'Baluchari Silk Saree (Bishnupur)', 'Meera Basak Weaves (Demo)', 'West Bengal', 'Bankura', 'Handloom', 12000, 5, 'https://images.unsplash.com/photo-1584697964154-3a05b5b0e16a?w=400&q=80', 'Authentic Baluchari saree with intricate mythological motifs woven on the pallu using traditional shuttle looms.', true),
('wb-kantha-embroidery', 'Kantha Embroidered Dupatta', 'Supriya Dey Crafts (Demo)', 'West Bengal', 'Murshidabad', 'Textiles', 1800, 12, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=400&q=80', 'Hand-stitched Kantha work dupatta featuring traditional fish, floral, and peacock motifs using running stitch technique.', true),
('wb-darjeeling-tea-gift', 'Darjeeling First Flush Tea Gift Box', 'Himalayan Tea Co. (Demo)', 'West Bengal', 'Darjeeling', 'Food & Beverage', 850, 25, 'https://images.unsplash.com/photo-1544568100-847a19cae382?w=400&q=80', 'Premium Darjeeling First Flush tea from select estates, packaged in a traditional wooden gift box with stamp motifs.', true),
('wb-murshidabad-silk', 'Murshidabad Pure Silk Stole', 'Nasreen Silk House (Demo)', 'West Bengal', 'Murshidabad', 'Handloom', 3500, 8, 'https://images.unsplash.com/photo-1584697964154-3a05b5b0e16a?w=400&q=80', 'Lustrous Murshidabad silk stole with delicate zari border, woven on traditional jacquard looms by master weavers.', true),
('bh-madhubani-painting', 'Madhubani Painting — Kohbar', 'Rambharos Jha Studio (Demo)', 'Bihar', 'Madhubani', 'Paintings', 4500, 6, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=400&q=80', 'Original Madhubani Kohbar painting on handmade paper depicting the sacred wedding chamber scene with fish, lotus, and bamboo motifs.', true),
('bh-sikki-grass-basket', 'Sikki Grass Jewellery Box', 'Kiran Devi Artisans (Demo)', 'Bihar', 'Sitamarhi', 'Bamboo & Grass', 650, 15, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=400&q=80', 'Intricate jewellery box made from golden Sikki grass, featuring traditional Mithila geometric patterns. Fully handmade.', true),
('bh-manjusha-art-box', 'Manjusha Art Lacquered Box', 'Bhagalpur Craft Guild (Demo)', 'Bihar', 'Bhagalpur', 'Paintings', 1200, 10, 'https://images.unsplash.com/photo-1583484963903-3d65c99f86de?w=400&q=80', 'Lacquered wooden box decorated with Manjusha folk art — a unique narrative art form depicting the story of Bihula-Bishahari.', true),
('jh-bamboo-craft-tribal', 'Tribal Bamboo Fruit Basket', 'Santosh Munda Crafts (Demo)', 'Jharkhand', 'Ranchi', 'Bamboo', 450, 20, 'https://images.unsplash.com/photo-1565073624-4e30d82d2e1f?w=400&q=80', 'Hand-woven tribal bamboo basket with natural dye patterns. Each piece is unique, following traditional Munda weaving techniques.', true),
('jh-dokra-metal-elephant', 'Dokra Metal Elephant Figurine', 'Dhokra Craft Center (Demo)', 'Jharkhand', 'West Singhbhum', 'Metal Art', 1800, 8, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=400&q=80', 'Lost-wax cast Dokra metal elephant using 4,000-year-old technique. Each piece is unique and handmade by tribal artisans.', true),
('jh-paitkar-painting', 'Paitkar Scroll Painting', 'Dukhushyam Chitrakar (Demo)', 'Jharkhand', 'East Singhbhum', 'Paintings', 2200, 5, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=400&q=80', 'Traditional Paitkar scroll painting used by chitrakar (painter) community for ritual storytelling. Features life, death, and rebirth narratives.', true)
INSERT INTO public.stamps (id, name, price, stock, category, state, city, year, rarity, image, description, is_active)
VALUES
('1', '1947 First Independence Series (Ashoka Lion Capital)', 12500, 1, 'History', 'Delhi', 'New Delhi', 1947, 'Legendary', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Stamp_of_India_-_1947_-_Colnect_163777_-_Ashoka_Lion_Capital_first_stamp_of_independent_India.jpeg/640px-Stamp_of_India_-_1947_-_Colnect_163777_-_Ashoka_Lion_Capital_first_stamp_of_independent_India.jpeg', 'The historic 3½ anna stamp issued on 21 November 1947, depicting the Lion Capital of Ashoka — India’s very first postage stamp as an independent nation.', true),
('2', '1948 First Flight to London (Air India)', 8900, 1, 'Transport', 'Maharashtra', 'Mumbai', 1948, 'Very Rare', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Air_India_Constellation_1948_stamp.jpg/640px-Air_India_Constellation_1948_stamp.jpg', 'Issued to commemorate Air India International’s inaugural Bombay-London Lockheed Constellation flight on 8 June 1948. A philatelic crown jewel.', true),
('3', '1952 Saint Poets of India — Kabir', 2400, 1, 'Culture', 'Uttar Pradesh', 'Varanasi', 1952, 'Rare', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Kabir_1952_stamp_of_India.jpg/640px-Kabir_1952_stamp_of_India.jpg', 'Part of the landmark 1952 Saints and Poets series. Depicts the mystic poet-philosopher Kabir sitting at his handloom composing devotional verse.', true),
('4', '1954 India Postage Centenary — 4 Annas Queen Victoria Reissue', 14500, 1, 'History', 'West Bengal', 'Kolkata', 1954, 'Legendary', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/India_1954_postage_centenary_stamp.jpg/640px-India_1954_postage_centenary_stamp.jpg', 'Issued on 1 October 1954 celebrating 100 years of India’s first stamps printed by the Survey Office in Calcutta in 1854.', true),
('5', '1963 Wildlife Series — Royal Bengal Tiger', 1800, 2, 'Wildlife', 'West Bengal', 'Sundarbans', 1963, 'Rare', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Tiger_1963_stamp_of_India.jpg/640px-Tiger_1963_stamp_of_India.jpg', 'Stunning multi-color stamp honoring the Royal Bengal Tiger of the Sundarbans. One of India Post’s finest wildlife engravings.', true),
('6', '1969 Mahatma Gandhi Birth Centenary', 950, 4, 'History', 'Gujarat', 'Porbandar', 1969, 'Uncommon', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Gandhi_1969_stamp_of_India.jpg/640px-Gandhi_1969_stamp_of_India.jpg', 'Issued on 2 October 1969 on the centenary of Mahatma Gandhi’s birth. Beautiful portrait format showing Bapu reading at Sevagram.', true),
('7', '1975 Aryabhata First Satellite Launch', 3200, 1, 'Science', 'Karnataka', 'Bengaluru', 1975, 'Rare', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Aryabhata_satellite_1975_stamp.jpg/640px-Aryabhata_satellite_1975_stamp.jpg', 'Commemorating the launch of India’s first satellite, Aryabhata, on 19 April 1975. A milestone issue celebrating India’s entry into space exploration.', true),
('8', '1982 IX Asian Games New Delhi (Appu the Elephant)', 650, 5, 'Culture', 'Delhi', 'New Delhi', 1982, 'Common', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Appu_Asian_Games_1982_stamp.jpg/640px-Appu_Asian_Games_1982_stamp.jpg', 'Featuring Appu, the dancing baby elephant mascot of the 1982 New Delhi Asiad. A beloved nostalgic issue for collectors across India.', true),
('9', '1998 Pokhran-II National Technology Day', 4500, 1, 'Military', 'Rajasthan', 'Pokhran', 1998, 'Very Rare', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Pokhran_II_1998_stamp_of_India.jpg/640px-Pokhran_II_1998_stamp_of_India.jpg', 'Celebrating India’s May 1998 peaceful nuclear tests and designated National Technology Day. Highly sought after commemorative issue.', true),
('10', '2016 UNESCO Nalanda Mahavihara World Heritage', 1200, 3, 'Monuments', 'Bihar', 'Nalanda', 2016, 'Uncommon', 'https://images.unsplash.com/photo-1544568100-847a19cae382?w=400&q=80', 'Special commemorative issue marking the UNESCO World Heritage inscription of the ancient monastic university of Nalanda in Bihar.', true)
